CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '' CHECK (length(full_name)<=100), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('admin','reader')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_library_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN auth.users u ON u.id=r.user_id WHERE r.user_id=auth.uid() AND r.role='admin' AND lower(u.email)='anacavalcante1998@gmail.com' AND u.email_confirmed_at IS NOT NULL) $$;
REVOKE ALL ON FUNCTION public.is_library_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_library_admin() TO authenticated,service_role;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_library_admin());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.handle_library_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'full_name',''),100)) ON CONFLICT(id) DO NOTHING; IF lower(NEW.email)='anacavalcante1998@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; ELSE INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'reader') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER library_account_created AFTER INSERT OR UPDATE OF email_confirmed_at,email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_library_account();
CREATE TABLE public.categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 60), slug text NOT NULL UNIQUE, description text, icon text DEFAULT 'book', icon_name text, image_path text, parent_id uuid REFERENCES public.categories(id) ON DELETE SET NULL, sort_order integer NOT NULL DEFAULT 0, is_active boolean DEFAULT true, created_by uuid REFERENCES public.profiles(id), created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY category_read ON public.categories FOR SELECT TO authenticated USING(true);
CREATE POLICY category_admin ON public.categories FOR ALL TO authenticated USING(public.is_library_admin()) WITH CHECK(public.is_library_admin());
CREATE TABLE public.books(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 300),author text CHECK(length(author)<=300),description text CHECK(length(description)<=10000),category_id uuid REFERENCES public.categories(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')),featured boolean DEFAULT false,is_featured boolean DEFAULT false,allow_download boolean NOT NULL DEFAULT false,source text NOT NULL DEFAULT 'drive' CHECK(source='drive'),drive_file_id text NOT NULL UNIQUE CHECK(drive_file_id ~ '^[A-Za-z0-9_-]{15,200}$'),cover_drive_id text CHECK(cover_drive_id ~ '^[A-Za-z0-9_-]{15,200}$'),cover_url text,cover_path text,views integer NOT NULL DEFAULT 0,published_at timestamptz,created_by uuid REFERENCES public.profiles(id),created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.books TO authenticated; GRANT ALL ON public.books TO service_role;
ALTER TABLE public.books ENABLE ROW LEVEL SECURITY;
CREATE POLICY books_published ON public.books FOR SELECT TO authenticated USING(status='published');
CREATE POLICY books_admin ON public.books FOR ALL TO authenticated USING(public.is_library_admin()) WITH CHECK(public.is_library_admin());
CREATE TABLE public.book_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),book_id uuid UNIQUE REFERENCES public.books(id) ON DELETE CASCADE,storage_path text,original_name text,size_bytes bigint);
GRANT SELECT ON public.book_files TO authenticated; GRANT ALL ON public.book_files TO service_role;
ALTER TABLE public.book_files ENABLE ROW LEVEL SECURITY;
CREATE POLICY files_read ON public.book_files FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.books WHERE id=book_id));
CREATE TABLE public.book_categories(book_id uuid REFERENCES public.books(id) ON DELETE CASCADE,category_id uuid REFERENCES public.categories(id) ON DELETE CASCADE,sort_order integer DEFAULT 0,PRIMARY KEY(book_id,category_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.book_categories TO authenticated; GRANT ALL ON public.book_categories TO service_role;
ALTER TABLE public.book_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY relations_read ON public.book_categories FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.books WHERE id=book_id));
CREATE POLICY relations_admin ON public.book_categories FOR ALL TO authenticated USING(public.is_library_admin()) WITH CHECK(public.is_library_admin());
CREATE TABLE public.favorites(user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,book_id uuid REFERENCES public.books(id) ON DELETE CASCADE,created_at timestamptz DEFAULT now(),PRIMARY KEY(user_id,book_id));
GRANT SELECT,INSERT,DELETE ON public.favorites TO authenticated; GRANT ALL ON public.favorites TO service_role;
ALTER TABLE public.favorites ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_favorites ON public.favorites FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.books WHERE id=book_id));
CREATE TABLE public.reading_history(user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE,book_id uuid REFERENCES public.books(id) ON DELETE CASCADE,last_page integer NOT NULL DEFAULT 1 CHECK(last_page>0),updated_at timestamptz DEFAULT now(),PRIMARY KEY(user_id,book_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.reading_history TO authenticated; GRANT ALL ON public.reading_history TO service_role;
ALTER TABLE public.reading_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_history ON public.reading_history FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.books WHERE id=book_id));
CREATE FUNCTION public.category_counts() RETURNS TABLE(category_id uuid,total bigint) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT category_id,count(*) FROM public.books WHERE status='published' GROUP BY category_id $$;
CREATE FUNCTION public.storage_used() RETURNS bigint LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT coalesce(sum(size_bytes),0)::bigint FROM public.book_files $$;
CREATE FUNCTION public.increment_views(p_book uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; UPDATE public.books SET views=views+1 WHERE id=p_book AND status='published'; END $$;
REVOKE ALL ON FUNCTION public.category_counts(),public.storage_used(),public.increment_views(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.category_counts(),public.storage_used(),public.increment_views(uuid) TO authenticated,service_role;